import{_ as t,a,c as o,ac as l}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 13 The search for oil","description":"学习 目的不定式与 so that，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 13 The search for oil","description":"学习 目的不定式与 so that，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 目的不定式与 so that，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 12 Banks and their customers","link":"/life/english/new-concept/book-4/unit-02/lesson-012"},"next":{"text":"第四册：流利英语 · Lesson 14 The Butterfly Effect","link":"/life/english/new-concept/book-4/unit-02/lesson-014"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 12 Banks and their customers","link":"/life/english/new-concept/book-4/unit-02/lesson-012"},"next":{"text":"第四册：流利英语 · Lesson 14 The Butterfly Effect","link":"/life/english/new-concept/book-4/unit-02/lesson-014"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-02/lesson-013.md","filePath":"life/english/new-concept/book-4/unit-02/lesson-013.md"}'),s={name:"life/english/new-concept/book-4/unit-02/lesson-013.md"};function n(i,e,r,h,c,d){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="第四册-流利英语-·-lesson-13-the-search-for-oil" tabindex="-1">第四册：流利英语 · Lesson 13 The search for oil <a class="header-anchor" href="#第四册-流利英语-·-lesson-13-the-search-for-oil" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 13 The search for oil&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>通过资源勘探主题练习程序性说明，按收集数据、解释线索、进一步检测的顺序组织信息。区分“有利迹象”与“已经找到可开采资源”，不把某项测量解释成确定发现。重点处理目的表达与结果表达，写出每一步为什么做及它仍不能解决的问题。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>survey</td><td>/ˈsɜːveɪ/</td><td>n.</td><td>勘测</td><td>a geological survey</td></tr><tr><td>sample</td><td>/ˈsɑːmpəl/</td><td>n.</td><td>样本</td><td>collect a sample</td></tr><tr><td>deposit</td><td>/dɪˈpɒzɪt/</td><td>n.</td><td>矿藏</td><td>an underground deposit</td></tr><tr><td>drill</td><td>/drɪl/</td><td>v.</td><td>钻探</td><td>drill a test well</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>carry out — 执行调查或实验</li><li>in search of — 寻找</li></ul><h2 id="语法讲解-目的不定式与-so-that" tabindex="-1">语法讲解：目的不定式与 so that <a class="header-anchor" href="#语法讲解-目的不定式与-so-that" aria-label="Permalink to &quot;语法讲解：目的不定式与 so that&quot;">​</a></h2><p>to、in order to 与 so as to 后接动词原形表达目的，通常与主句行为的执行者一致。so that 后接完整从句，适合主语不同或需要 can、could 等情态动词的情况。The team mapped the area to choose a site. 中测绘者和选择者相同。目的说明的是意图，不保证成功；to find oil 不能单凭语法推出确实找到了石油。否定目的可用 in order not to。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The team collected rock samples so that specialists could compare the layers.</p></blockquote><p>团队收集岩石样本，以便专家比较地层。</p><p>so that 从句有独立主语 specialists，与主句 team 不同；could compare 表当时的目的。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要把 to collect 与 because collected 混淆：前者说明目的，后者说明已经发生的原因。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 to compare 时弱读 to，读 so that specialists could 时把 specialists 重读，听辨执行者是否改变。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We collected samples to compare the rock layers. The results may reveal differences in their structure. Further testing will be needed before any conclusion is drawn.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句说明一次虚构勘测：采集什么、为何分析、下一步取决于什么。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>目的、可能发现、结论限制依次展开，没有把勘测等同于资源发现。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中收集者和比较者的称呼分别是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the team 和 specialists</p><p><strong>解析：</strong> 两个分句的主语分别指明角色。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：They marked the site in order ___ return later.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> in order to 后接动词原形。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>“They drilled to test the rock.” 是否保证发现资源？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不保证。</p><p><strong>解析：</strong> to test 只说明钻探目的。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：目的不定式与 so that。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-012">上一课</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-02/lesson-014">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=t(s,[["render",n]]);export{u as __pageData,f as default};
